export const htmlEscape = (value = "") =>String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");export const attrEscape = (value = "") => htmlEscape(value).replaceAll("'", "&#39;");export const normalizeUrl = (value) => {const trimmed = String(value || "").trim();if (!trimmed) return "";try {return new URL(trimmed).toString();} catch {return trimmed;}};export const field = ({ id, label, value = "", type = "text", help = "", full = false, attrs = "" }) => `<div class="field ${full ? "full" : ""}"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${attrEscape(value)}" ${attrs}>${help ? `<small>${help}</small>` : ""}</div>`;export const textarea = ({ id, label, value = "", help = "", full = true }) => `<div class="field ${full ? "full" : ""}"><label for="${id}">${label}</label><textarea id="${id}">${htmlEscape(value)}</textarea>${help ? `<small>${help}</small>` : ""}</div>`;export const select = ({ id, label, options, value = "", full = false }) => `<div class="field ${full ? "full" : ""}"><label for="${id}">${label}</label><select id="${id}">${options.map((item) => `<option value="${attrEscape(item.value)}" ${item.value === value ? "selected" : ""}>${htmlEscape(item.label)}</option>`).join("")}</select></div>`;export const checkbox = ({ id, label, checked = false }) => `<label class="check-row"><input id="${id}" type="checkbox" ${checked ? "checked" : ""}><span>${label}</span></label>`;function mountTool(root, config) {const outputLabel = root.dataset.outputLabel || "Output";const copyLabel = root.dataset.copyLabel || "Copy";const copiedLabel = root.dataset.copiedLabel || "Copied";root.innerHTML = `<div class="tool-layout"><form class="tool-panel" data-role="form">${config.form}</form><div class="result-box"><div class="result-header"><h2>${htmlEscape(outputLabel)}</h2><button class="copy-button" type="button" data-role="copy" aria-label="Copy output to clipboard">${htmlEscape(copyLabel)}</button></div><pre class="output" data-role="output" tabindex="0" aria-live="polite" aria-label="Tool output"></pre><div data-role="preview"></div><div class="copy-status" data-role="copy-status" role="status" aria-live="assertive"></div></div></div>`;const form = root.querySelector("[data-role='form']");const output = root.querySelector("[data-role='output']");const preview = root.querySelector("[data-role='preview']");const copy = root.querySelector("[data-role='copy']");const copyStatus = root.querySelector("[data-role='copy-status']");const update = () => {const result = config.generate(root);output.textContent = result.output;preview.innerHTML = result.preview || "";};form.addEventListener("input", update);form.addEventListener("change", update);copy.addEventListener("click", async () => {try {await navigator.clipboard.writeText(output.textContent);copy.textContent = copiedLabel;copyStatus.textContent = "Copied to clipboard";setTimeout(() => {copy.textContent = copyLabel;copyStatus.textContent = "";}, 1200);} catch {copyStatus.textContent = "Copy failed. Select and copy the output manually.";}});update();}function hexToRgb(hex) {const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);return result ? {r: parseInt(result[1], 16),g: parseInt(result[2], 16),b: parseInt(result[3], 16)} : { r: 0, g: 0, b: 0 };}function relativeLuminance({ r, g, b }) {const [rs, gs, bs] = [r, g, b].map((c) => {const s = c / 255;return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);});return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;}function contrastRatio(hex1, hex2) {const lum1 = relativeLuminance(hexToRgb(hex1));const lum2 = relativeLuminance(hexToRgb(hex2));const lighter = Math.max(lum1, lum2);const darker = Math.min(lum1, lum2);return (lighter + 0.05) / (darker + 0.05);}if (typeof document !== "undefined") {document.querySelectorAll("[data-tool-id]").forEach((root) => {const id = root.dataset.toolId;import(`/assets/tools/${id}.js`).then((mod) => mountTool(root, mod.default)).catch(() => {root.innerHTML = `<p>This tool is not loaded. <a href="/tools/">Browse available tools</a>.</p>`;});});}